<?php if (!$products): ?><div class="empty">هنوز محصولی برای نمایش ثبت نشده است.</div><?php else: ?><div class="products"><?php foreach ($products as $item): ?><a class="product-card" href="<?= site_url('product/' . rawurlencode($item['slug'])) ?>"><div class="product-image"><?php if (!empty($item['image_url'])): ?><img src="<?= esc($item['image_url'], 'attr') ?>" alt="<?= esc($item['name'], 'attr') ?>" loading="lazy"><?php else: ?>تصویر محصول<?php endif; ?></div><div class="product-info"><h3><?= esc($item['name']) ?></h3><div class="price"><?= number_format((int)$item['price_toman']) ?> تومان</div></div></a><?php endforeach; ?></div><?php endif; ?>